solution.css:
.page {
  width: 860px; /* fixed for this exercise */
  display: grid;
  gap: 20px;
}
.site-header, .filters, .speaker {
  padding: 12px;
  border-radius: 10px;
  background: #f5f3ff;
}
.page {
  grid-template-columns: 200px minmax(0, 1fr);
  grid-template-areas:
    "header  header"
    "filters main";
}
.site-header { grid-area: header; }
.filters { grid-area: filters; }
.speakers { grid-area: main; }

.speakers {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
  gap: 16px;
}
.speaker.featured {
  grid-column: 1 / -1;
}
